//!Game bridge of646b0; only verified raw UNIT and roster fields are read.
use super::{Actor,query,admitted,scatter};use crate::{Game,original_combat};
impl Game{
 pub(crate) fn native_projectile_warning(&mut self,index:usize,target:[i16;2]){if !self.map.original{return;}self.native_query_shape=super::SHAPE_POINTER;let Some(shooter)=self.units.get(index).and_then(|u|u.native_slot).and_then(|slot|self.native_group_rosters.members[slot].as_ref())else{return;};let shooter_group=shooter.group;
  let mut actors=self.units.iter().filter_map(|u|{let slot=u.native_slot?;let m=self.native_group_rosters.members.get(slot)?.as_ref()?;let p=[if u.native_transport.as_ref().is_some_and(|t|t.phase==crate::original_transport::Phase::Inside){10000}else{(u.x/2.).floor()as i16},(u.y/2.).floor()as i16];Some(Actor{slot:slot as u8,position:p,family:original_combat::animation_family(&u.kind)as i8,class:u.native_class7c,flags31:m.flags31,flags8a:m.flags8a,phase:u.native_phase35,aim:u.original_combat.as_ref().map_or(0,|c|c.aim_skill as i8),role:m.role,group:m.group})}).collect::<Vec<_>>();actors.sort_by_key(|a|a.slot);let Some(target)=query(&actors,target)else{return;};let Some(g)=self.native_group_rosters.pool.get(usize::from(target.group))else{return;};if !admitted(shooter_group,target,g.roster[61]){return;}let group=usize::from(target.group);if g.roster[63]==0{let roster=g.roster[19..40].to_vec();let previous=self.native_group_rosters.current_roster;self.native_group_rosters.current_roster=Some(group);for slot in roster.into_iter().filter(|&s|s!=255){let first=self.native_random();let second=self.native_random();if let Some(i)=self.units.iter().rposition(|u|u.native_slot==Some(usize::from(slot))){let u=&self.units[i];let position=[(u.x/2.).floor()as i16,(u.y/2.).floor()as i16];let aim=u.original_combat.as_ref().map_or(0,|c|c.aim_skill as i8);let point=scatter(position,aim,first,second);self.units[i].motion_bonus=2;self.start_native_walking_direct(i,point);}}self.native_group_rosters.current_roster=previous;}
  self.native_group_rosters.pool[group].roster[9]&=!1;self.native_group_rosters.pool[group].roster[63]=68;
 }
}

#[cfg(test)]mod tests{use super::*;use crate::{original_group_game,original_combat::OriginalRng,original_route,original_formation};
 fn field()->Game{let mut g=Game::new(0,1,0x646b0);g.map.original=true;g.map.width=64;g.map.height=64;g.map.tiles=vec![0;4096];g.map.terrain_codes=vec![0;4096];g.map.native_terrain_plane=vec![0;16384];g.map.native_road_graph=Some(original_route::RoadGraph{regions:vec![]});g.units.clear();g.buildings.clear();g.crates.clear();g.walls.clear();g.objects.clear();g.native_group_rosters=original_group_game::State::default();g.spawn("medium",0,300.,300.,10,None);g.spawn("grunt",1,1024.,1024.,20,None);g.spawn("sniper",1,1080.,1024.,20,None);g.maintain_native_group_rosters();g.native_group_rosters.set_current_roster(0,10);let group=g.native_group_rosters.group_slot(1,20).unwrap();g.native_group_rosters.pool[group].roster[61]=0;g.native_group_rosters.pool[group].roster[63]=0;for u in &g.units{if let Some(slot)=u.native_slot{g.native_routes.get_mut().managed[slot]=true;}}g.original_rng=OriginalRng::seeded(12123);g}
 #[test]fn warning_scatter_keeps_primary_routes_uses_two_draws_per_role_and_never_sets_dodge(){let mut g=field();let group=g.native_group_rosters.group_slot(1,20).unwrap();let previous=g.native_group_rosters.current_roster;let slot=g.units[2].native_slot.unwrap();let link=g.native_routes.get_mut().pool.allocate_goal([760,760]).unwrap();g.native_routes.get_mut().pool.links[slot].primary=link;g.units[2].order="move".into();g.units[2].formation=Some(original_formation::Follow::new(g.units[1].id,1,0,(1500.,1500.),0,0));g.units[1].native_speed8b=0;g.units[1].native_phase35=1;g.units[1].native_frame32=99;g.units[1].native_timer3c=8;let mut expected=g.original_rng.clone();for _ in 0..4{expected.next_u32();}g.native_projectile_warning(0,[520,520]);assert_eq!(g.original_rng.words,expected.words);assert_eq!(g.native_group_rosters.current_roster,previous);assert_eq!(g.native_group_rosters.pool[group].roster[63],68);assert_eq!(g.native_group_rosters.pool[group].roster[9]&1,0);assert_eq!(g.units[1].native_phase35,2);assert_eq!(g.units[1].native_timer3c,8,"525a0 uses prepared8b, not the new8c bonus");assert_eq!(g.units[2].motion_bonus,2);assert_eq!(g.units[2].native_flags64&64,0);assert!(g.units[2].native_dodge.is_none());assert_eq!(g.native_routes.borrow().pool.links[slot].primary,link);let remaining=g.units[2].native_remaining48;let heading=g.units[2].original_motion.as_ref().unwrap().heading();g.update_native_follower(2);assert_eq!(g.units[2].native_remaining48,remaining);assert_eq!(g.units[2].original_motion.as_ref().unwrap().heading(),heading);g.native_projectile_warning(0,[520,520]);assert_eq!(g.original_rng.words,expected.words);assert_eq!(g.native_query_shape,super::super::SHAPE_POINTER);}
 #[test]fn first_unit_query_match_can_block_a_later_eligible_robot(){let mut g=field();g.units[0].x=1024.;g.units[0].y=1024.;let before=g.original_rng.words;g.native_projectile_warning(0,[520,520]);assert_eq!(g.original_rng.words,before);let group=g.native_group_rosters.group_slot(1,20).unwrap();assert_eq!(g.native_group_rosters.pool[group].roster[63],0);assert_eq!(g.units[1].native_phase35,0);}
}
